using System.Reflection;
using System.Runtime.InteropServices;
using OcctSharp.CopiedCollections;
using OcctSharp.Generated;
using OcctSharp.Values;
using Workflow=OcctSharp.Tests.Shared.BatchAHBulkAnalysisWorkflow;
namespace OcctSharp.Runtime.Tests;

public sealed class BulkAnalysisTests
{
    [Fact]public void CompleteSharedWorkflow()=>Workflow.Run();
    [Fact]public void KnotAnalysisAndCompressedExpandedDataAgree(){var k=new CopiedArray<double>([0,0.3,1]);var m=new CopiedArray<int>([3,1,3]);Assert.Equal(4,BSplCLibCollections.NbPoles(2,false,m));Assert.Equal(1,BSplCLibCollections.FirstUKnotIndex(2,m));Assert.Equal(3,BSplCLibCollections.LastUKnotIndex(2,m));Assert.Equal(4,BSplCLibCollections.FlatIndex(2,2,m,false));Assert.Equal(1,BSplCLibCollections.PoleIndex(2,2,false,m));Assert.Equal(1,BSplCLibCollections.MinKnotMult(m,1,3));_ = BSplCLibCollections.MultForm(m,1,3);_ = BSplCLibCollections.KnotForm(k,1,3);GeomAbsBSplKnotDistribution form=default;int max=0;BSplCLibCollections.KnotAnalysis(2,false,k,m,ref form,ref max);Assert.Equal(1,max);int size=BSplCLibCollections.KnotSequenceLength(m,2,false);var flat=new CopiedArray<double>(new double[size]);BSplCLibCollections.KnotSequence(k,m,ref flat,false);Assert.Equal(new double[]{0,0,0,0.3,1,1,1},flat.ToArray());Assert.Equal(3,BSplCLibCollections.KnotsLength(flat,false));var compressed=new CopiedArray<double>(new double[3]);var mult=new CopiedArray<int>(new int[3]);BSplCLibCollections.Knots(flat,ref compressed,ref mult,false);Assert.Equal(k.ToArray(),compressed.ToArray());Assert.Equal(m.ToArray(),mult.ToArray());}
    [Fact]public void HuntHandlesEndpointsWithoutChangingInput(){var a=new CopiedArray<double>([0,0.5,1]);int index=77;BSplCLibCollections.Hunt(a,-1,ref index);Assert.Equal(0,index);BSplCLibCollections.Hunt(a,2,ref index);Assert.Equal(4,index);BSplCLibCollections.Hunt(a,0.3,ref index);Assert.Equal(1,index);Assert.Equal(new double[]{0,0.5,1},a.ToArray());}
    [Fact]public void PreparationCountsAgreeWithOwnedEdits(){using var c=Workflow.Curve();var k=GeomBSplineCurveCollections.Knots(c);var m=GeomBSplineCurveCollections.Multiplicities(c);Assert.Equal(2,BSplCLibCollections.IncreaseDegreeCountKnots(3,5,false,m));int knots=0,poles=0;BSplCLibCollections.PrepareTrimming(3,false,k,m,0.2,0.8,ref knots,ref poles);c.Segment(0.2,0.8,1e-12);Assert.Equal(c.NbKnots(),knots);Assert.Equal(c.NbPoles(),poles);}
    [Fact]public void PeriodicExpansionAndUnperiodizationSizesAgree(){var m=new CopiedArray<int>([1,1,1,1,1]);var k=new CopiedArray<double>([0,1,2,3,4]);int n=BSplCLibCollections.KnotSequenceLength(m,2,true);var flat=new CopiedArray<double>(new double[n]);BSplCLibCollections.KnotSequence(k,m,2,true,ref flat);Assert.Equal(new double[]{-2,-1,0,1,2,3,4,5,6},flat.ToArray());int knots=0,poles=0;BSplCLibCollections.PrepareUnperiodize(2,m,ref knots,ref poles);Assert.Equal(9,knots);Assert.Equal(6,poles);}
    [Fact]public void NumericErrorsPreserveManagedRefs(){var bad=new CopiedArray<double>([0,1],-1);int index=77;Assert.Throws<ArgumentException>(()=>BSplCLibCollections.Hunt(bad,0.2,ref index));Assert.Equal(77,index);var k=new CopiedArray<double>([0,1]);var m=new CopiedArray<int>([3,3]);var output=new CopiedArray<double>([99]);var identity=output;Assert.Throws<ArgumentException>(()=>BSplCLibCollections.KnotSequence(k,m,2,false,ref output));Assert.Same(identity,output);Assert.Throws<ArgumentException>(()=>BSplCLibCollections.FirstUKnotIndex(25,new([1,1])));Assert.Throws<ArgumentException>(()=>BSplCLibCollections.NbPoles(2,false,new([int.MaxValue,int.MaxValue])));}
    [Fact]public void UnitWeightsAreIndependentStaticCopies(){var a=BSplCLibCollections.UnitWeights(4);var b=a.ToArray();b[0]=7;Assert.All(BSplCLibCollections.UnitWeights(4).ToArray(),x=>Assert.Equal(1,x));var grid=BSplSLibCollections.UnitWeights(2,3);Assert.Equal(6,grid.ToArray().Length);Assert.All(grid.ToArray(),x=>Assert.Equal(1,x));Assert.Throws<ArgumentException>(()=>BSplCLibCollections.UnitWeights(0));Assert.Throws<ArgumentException>(()=>BSplSLibCollections.UnitWeights(int.MaxValue,2));}
    [Theory][InlineData(true)][InlineData(false)]public void PackedRationalSurfaceRoundtripBothDirections(bool u){var p=new CopiedGrid<Coordinates3d>([new(1,2,3),new(2,3,4),new(3,4,5),new(4,5,6),new(5,6,7),new(6,7,8)],2,3);var w=new CopiedGrid<double>([1,2,3,2,1,4],2,3);var packed=new CopiedArray<double>(new double[24]);BSplSLibCollections.SetPoles(p,w,ref packed,u);var restored=new CopiedGrid<Coordinates3d>(new Coordinates3d[6],2,3);var weights=new CopiedGrid<double>(new double[6],2,3);BSplSLibCollections.GetPoles(packed,ref restored,ref weights,u);Assert.Equal(p.ToArray(),restored.ToArray());Assert.Equal(w.ToArray(),weights.ToArray());}
    [Theory][InlineData(true)][InlineData(false)]public void GridReverseCopiesAndChecksPivot(bool u){var p=new CopiedGrid<double>([1,2,3,4,5,6],2,3);var old=p;BSplSLibCollections.Reverse(ref p,u?2:3,u);Assert.Equal(u?new double[]{4,5,6,1,2,3}:new double[]{3,2,1,6,5,4},p.ToArray());Assert.Equal(new double[]{1,2,3,4,5,6},old.ToArray());Assert.Throws<ArgumentException>(()=>BSplSLibCollections.Reverse(ref p,0,u));}
    [Fact]public void RationalityReportsPinnedSemantics(){Assert.True(BSplCLibCollections.IsRational(new([1.0,2,1]),1,3,100));Assert.False(BSplCLibCollections.IsRational(new([1.0,1,1]),1,3,0));Assert.True(BSplSLibCollections.IsRational(new([1.0,1,2,2],2,2),1,2,1,2,1e-9));Assert.Throws<ArgumentException>(()=>BSplSLibCollections.IsRational(new([1.0,1,2,2],2,2),1,2,1,2,0));}
    [Fact]public void CoefficientsHaveExactOutputShapes(){var p=new CopiedArray<Coordinates3d>([new(0,0,0),new(1,2,0),new(2,0,0)]);var c=new CopiedArray<Coordinates3d>(new Coordinates3d[3]);BSplCLibCollections.PolesCoefficients(p,ref c);Assert.Equal(new Coordinates3d(0,0,0),c[1]);var p2=new CopiedArray<Point2d>([new(0,0),new(1,2),new(2,0)]);var c2=new CopiedArray<Point2d>(new Point2d[3]);BSplCLibCollections.PolesCoefficients(p2,ref c2);Assert.Equal(c[2].X,c2[2].X);var grid=new CopiedGrid<Coordinates3d>([new(0,0,0),new(0,1,0),new(1,0,0),new(1,1,0)],2,2);var cg=new CopiedGrid<Coordinates3d>(new Coordinates3d[4],2,2);BSplSLibCollections.PolesCoefficients(grid,ref cg);Assert.Equal(grid[1,1],cg[1,1]);}
    [Fact]public void CoefficientPolynomialsAgreeWithOwningEvaluators(){var poles=new CopiedArray<Coordinates3d>([new(0,1,0),new(1,2,1),new(3,-1,2)]);var coefficients=new CopiedArray<Coordinates3d>(new Coordinates3d[3]);BSplCLibCollections.PolesCoefficients(poles,ref coefficients);using var curve=GeomBezierCurveCollections.Create(poles);for(int i=0;i<=20;++i){double u=i/20.0;var p=curve.EvalD0(u);Assert.Equal(p.X,coefficients[1].X+coefficients[2].X*u+coefficients[3].X*u*u,10);Assert.Equal(p.Y,coefficients[1].Y+coefficients[2].Y*u+coefficients[3].Y*u*u,10);}var grid=new CopiedGrid<Coordinates3d>([new(0,0,0),new(0,2,1),new(0,3,-1),new(2,0,1),new(2,2,-2),new(2,3,3)],2,3);var coefs=new CopiedGrid<Coordinates3d>(new Coordinates3d[6],2,3);BSplSLibCollections.PolesCoefficients(grid,ref coefs);using var surface=GeomBezierSurfaceCollections.Create(grid);for(int i=0;i<=10;++i){double u=i/10.0,v=1-u;double z=0;for(int r=1;r<=2;++r)for(int c=1;c<=3;++c)z+=coefs[r,c].Z*Math.Pow(u,r-1)*Math.Pow(v,c-1);Assert.Equal(surface.EvalD0(u,v).Z,z,9);}}
    [Fact]public void PackedFailuresPublishNothing(){var p=new CopiedGrid<Coordinates3d>(new Coordinates3d[6],2,3);var shortOutput=new CopiedArray<double>([99]);var old=shortOutput;Assert.Throws<ArgumentException>(()=>BSplSLibCollections.SetPoles(p,ref shortOutput,true));Assert.Same(old,shortOutput);var w=new CopiedGrid<double>(new double[6],2,3);var original=p;var weights=w;Assert.Throws<ArgumentException>(()=>BSplSLibCollections.GetPoles(new(new double[24]),ref p,ref w,true));Assert.Same(original,p);Assert.Same(weights,w);}
    [Theory][InlineData(true)][InlineData(false)]public void CurveSetAndSingletonSplitDeepCopy(bool angular){using var c=Workflow.Curve();using var set=OwnedCurveSet3d.Create(c);using var split=angular?GeomConvertCollections.C0BSplineToArrayOfC1BSplineCurve(c,1e-7,1e-6):GeomConvertCollections.C0BSplineToArrayOfC1BSplineCurve(c,1e-7);c.SetPole(1,new(999,999,999));using var a=set.GetCurve(0);using var b=split.GetCurve(0);Assert.Equal(0,a.StartPoint().X);Assert.Equal(0,b.StartPoint().X);set.Dispose();split.Dispose();Assert.Equal(3,a.EndPoint().X);Assert.Equal(3,b.EndPoint().X);Assert.Throws<ObjectDisposedException>(()=>set.GetCurve(0));}
    [Theory][InlineData(true)][InlineData(false)]public void CornerSplitPreservesOrderAndSamples(bool two){if(two){using var c=Geom2dBSplineCurveCollections.Create(new([new Point2d(0,0),new(0.5,0),new(1,0),new(1,0.5),new(1,1)]),new([0.0,0.5,1]),new([3,2,3]),2,false);using var s=Geom2dConvertCollections.C0BSplineToArrayOfC1BSplineCurve(c,1e-8);Assert.Equal(2,s.Count);for(int i=0;i<s.Count;++i){using var q=s.GetCurve(i);var p=c.EvalD0((q.FirstParameter()+q.LastParameter())/2);var p2=q.EvalD0((q.FirstParameter()+q.LastParameter())/2);Assert.Equal(p.X,p2.X,10);Assert.Equal(p.Y,p2.Y,10);}}else{using var c=GeomBSplineCurveCollections.Create(new([new Coordinates3d(0,0,0),new(0.5,0,0),new(1,0,0),new(1,0.5,0),new(1,1,0)]),new([0.0,0.5,1]),new([3,2,3]),2,false);using var s=GeomConvertCollections.C0BSplineToArrayOfC1BSplineCurve(c,1e-8);Assert.Equal(2,s.Count);using var q=s.GetCurve(1);Assert.Equal(0.5,q.FirstParameter(),10);Assert.Equal(1,q.EndPoint().Y,10);}}
    [Theory][InlineData(0)][InlineData(1)][InlineData(2)]public void ThreeDimensionalConcatVariantsHaveIndependentResults(int mode){using var a=Line3(0,1);using var b=Line3(1,2);using var s=OwnedCurveSet3d.Create(a,b);using var result=mode switch{0=>GeomConvertCollections.ConcatG1(s,new([1e-8]),false,1e-8),1=>GeomConvertCollections.ConcatC1(s,new([1e-8]),false,1e-8),_=>GeomConvertCollections.ConcatC1(s,new([1e-8]),false,1e-8,1e-6)};Assert.False(result.ClosedG1);_ = result.Indices;using var outputs=result.Curves;using var inputs=result.InputCurves;using var c=outputs.GetCurve(0);result.Dispose();s.Dispose();a.Dispose();b.Dispose();Assert.Equal(2,inputs.Count);Assert.Equal(2,c.EndPoint().X,8);c.SetPole(1,new(9,0,0));using var another=outputs.GetCurve(0);Assert.Equal(0,another.StartPoint().X,8);}
    [Fact]public void ConcatRejectsDisconnectedAndMalformedInputs(){using var a=Line3(0,1);using var b=Line3(3,4);using var s=OwnedCurveSet3d.Create(a,b);Assert.Throws<OcctException>(()=>GeomConvertCollections.ConcatC1(s,new([1e-8]),false,1e-8));Assert.Throws<ArgumentException>(()=>GeomConvertCollections.ConcatC1(s,new([1e-8,1e-8]),false,1e-8));Assert.Throws<ArgumentException>(()=>GeomConvertCollections.ConcatG1(s,new([-1.0]),false,1e-8));Assert.Throws<ArgumentException>(()=>OwnedCurveSet3d.Create());Assert.Throws<ArgumentNullException>(()=>OwnedCurveSet3d.Create(a,null!));}
    [Fact]public void CurveSetsSurviveGcAndConcurrentDisposal(){for(int repeat=0;repeat<25;++repeat){using var c=Workflow.Curve();var s=OwnedCurveSet3d.Create(c);using var independent=s.GetCurve(0);GC.Collect();Parallel.Invoke(()=>{for(int i=0;i<20;++i){try{using var q=s.GetCurve(0);Assert.Equal(3,q.EndPoint().X);}catch(ObjectDisposedException){}}},()=>s.Dispose());s.Dispose();Assert.Equal(3,independent.EndPoint().X);}}
    [Theory][InlineData(0)][InlineData(1)][InlineData(2)]public void TwoDimensionalConcatVariants(int mode){using var a=Geom2dBSplineCurveCollections.Create(new([new Point2d(0,0),new(0.5,0),new(1,0)]),new([0.0,1]),new([3,3]),2,false);using var b=Geom2dBSplineCurveCollections.Create(new([new Point2d(1,0),new(1.5,0),new(2,0)]),new([0.0,1]),new([3,3]),2,false);using var set=OwnedCurveSet2d.Create(a,b);using var result=mode switch{0=>Geom2dConvertCollections.ConcatG1(set,new([1e-8]),false,1e-8),1=>Geom2dConvertCollections.ConcatC1(set,new([1e-8]),false,1e-8),_=>Geom2dConvertCollections.ConcatC1(set,new([1e-8]),false,1e-8,1e-6)};using var output=result.Curves;using var c=output.GetCurve(0);Assert.Equal(2,c.EndPoint().X,8);using var split=Geom2dConvertCollections.C0BSplineToArrayOfC1BSplineCurve(c,1e-8,1e-6);Assert.Equal(1,split.Count);}
    [Fact]public void PeriodicJoinOfRationalQuarterCircles(){Coordinates3d[][] poles=[[new(1,0,0),new(1,1,0),new(0,1,0)],[new(0,1,0),new(-1,1,0),new(-1,0,0)],[new(-1,0,0),new(-1,-1,0),new(0,-1,0)],[new(0,-1,0),new(1,-1,0),new(1,0,0)]];var curves=poles.Select(p=>GeomBSplineCurveCollections.Create(new(p),new([1.0,Math.Sqrt(0.5),1]),new([0.0,1]),new([3,3]),2,false,true)).ToArray();try{using var set=OwnedCurveSet3d.Create(curves);using var result=GeomConvertCollections.ConcatC1(set,new([1e-7,1e-7,1e-7]),true,1e-7,1e-6);using var output=result.Curves;Assert.Equal(1,output.Count);Assert.True(result.ClosedG1);using var c=output.GetCurve(0);Assert.True(c.IsClosed());for(int i=0;i<20;++i){double u=c.FirstParameter()+(c.LastParameter()-c.FirstParameter())*i/20;var p=c.EvalD0(u);Assert.Equal(1,p.X*p.X+p.Y*p.Y,6);}}finally{foreach(var c in curves)c.Dispose();}}
    [Fact]public void ReversedInputsAndStrictJunctionToleranceReportFailure(){using var a=Line3(0,1);using var b=Line3(1,2);b.Reverse();using var set=OwnedCurveSet3d.Create(a,b);Assert.Throws<OcctException>(()=>GeomConvertCollections.ConcatC1(set,new([1e-8]),false,1e-8));using var gap=Line3(1.0001,2);using var near=OwnedCurveSet3d.Create(a,gap);Assert.Throws<OcctException>(()=>GeomConvertCollections.ConcatC1(near,new([1e-8]),false,1e-8));}
    [Fact]public void AliasedManagedCopiesHaveIndependentStorage(){var p=new CopiedArray<Point2d>([new(0,0),new(1,2),new(2,0)]);var old=p;BSplCLibCollections.PolesCoefficients(p,ref p);Assert.Equal(new Point2d(1,2),old[2]);Assert.NotSame(old,p);}
    [UnmanagedFunctionPointer(CallingConvention.Cdecl)]delegate int CountRaw(nint token,out int count);
    [UnmanagedFunctionPointer(CallingConvention.Cdecl)]delegate void ReleaseRaw(nint token,int kind);
    [UnmanagedFunctionPointer(CallingConvention.Cdecl)]unsafe delegate int InfoRaw(nint token,int* values,int capacity,out int count,out int closed);
    [UnmanagedFunctionPointer(CallingConvention.Cdecl)]unsafe delegate int InfoPointers(nint token,int* values,int capacity,int* count,int* closed);
    static nint Token(object owner)=>(owner.GetType().GetField("handle",BindingFlags.Instance|BindingFlags.NonPublic)!.GetValue(owner) as SafeHandle)!.DangerousGetHandle();
    [Fact]public unsafe void RawTypedTokensCapacityAndStaleOutputs(){_ = OcctRuntime.Info;nint library=NativeLibrary.Load(Path.Combine(AppContext.BaseDirectory,"occt","OcctSharp.Native.dll"));try{T Export<T>(string name)where T:Delegate=>Marshal.GetDelegateForFunctionPointer<T>(NativeLibrary.GetExport(library,name));var count=Export<CountRaw>("occtsharp_curves_3d_count");var wrong=Export<CountRaw>("occtsharp_curves_2d_count");var release=Export<ReleaseRaw>("occtsharp_curve_collection_release");using var a=Line3(0,1);using var b=Line3(1,2);using var set=OwnedCurveSet3d.Create(a,b);nint token=Token(set);Assert.Equal(0,count(token,out int n));Assert.Equal(2,n);Assert.NotEqual(0,wrong(token,out n));Assert.Equal(0,n);release(token,1);Assert.Equal(0,count(token,out n));using var result=GeomConvertCollections.ConcatC1(set,new([1e-8]),false,1e-8);var info=Export<InfoRaw>("occtsharp_curves_3d_result_info");Assert.Equal(0,info(Token(result),null,0,out n,out _));Assert.True(n>0);int sentinel=123;Assert.NotEqual(0,info(Token(result),&sentinel,0,out int written,out int closed));Assert.Equal(0,written);Assert.Equal(0,closed);Assert.Equal(123,sentinel);var pointers=Export<InfoPointers>("occtsharp_curves_3d_result_info");int alias=123;Assert.NotEqual(0,pointers(Token(result),null,0,&alias,&alias));Assert.Equal(123,alias);int flag=456;Assert.NotEqual(0,pointers(Token(result),&alias,1,&alias,&flag));Assert.Equal(123,alias);Assert.Equal(456,flag);release(token,0);Assert.NotEqual(0,count(token,out n));Assert.Equal(0,n);}finally{NativeLibrary.Free(library);}}
    static GeomBSplineCurve Line3(double start,double end)=>GeomBSplineCurveCollections.Create(new([new Coordinates3d(start,0,0),new((start+end)/2,0,0),new(end,0,0)]),new([0.0,1]),new([3,3]),2,false);
}
